"""Feature definitions and cleaning, shared by training (`training/train.py`) and serving (`app/`).

The ReneWind notebook's approach (predict failures from sensor readings, choose the model by the
real cost of mistakes), rebuilt as plain, tested functions on an openly licensed dataset. Training
and the API both import this module, so preprocessing can't drift between them.

Dataset: AI4I 2020 Predictive Maintenance (Matzka, 2020), UCI ML Repository, CC BY 4.0. It is
*synthetic*: generated by its author to reflect real milling-machine behaviour.
https://archive.ics.uci.edu/dataset/601/ai4i+2020+predictive+maintenance+dataset
"""

from __future__ import annotations

import math
from dataclasses import dataclass, field
from typing import Any, Literal

import pandas as pd

TARGET = "failure"


@dataclass(frozen=True)
class Field:
    """One model input. Drives training columns, request validation and the demo form."""

    name: str
    label: str
    kind: Literal["number", "category"]
    group: Literal["machine", "conditions", "operation"]
    help: str
    source_column: str
    options: tuple[str, ...] = ()
    minimum: float | None = None
    maximum: float | None = None
    step: float | None = None
    unit: str | None = None
    optional: bool = False
    option_labels: dict[str, str] = field(default_factory=dict)

    def to_schema(self) -> dict[str, Any]:
        schema: dict[str, Any] = {
            "name": self.name,
            "label": self.label,
            "kind": self.kind,
            "group": self.group,
            "help": self.help,
            "optional": self.optional,
        }
        if self.kind == "category":
            schema["options"] = [
                {"value": value, "label": self.option_labels.get(value, _humanize(value))}
                for value in self.options
            ]
        else:
            schema.update(
                {"min": self.minimum, "max": self.maximum, "step": self.step, "unit": self.unit}
            )
        return schema


def _humanize(value: str) -> str:
    return value.replace(".", " ").replace("-", " ").replace("_", " ").strip().capitalize()


FIELDS: tuple[Field, ...] = (
    Field(
        "machine_type",
        "Product quality variant",
        "category",
        "machine",
        "Quality variant of the product being machined (low, medium or high).",
        "Type",
        options=("L", "M", "H"),
        option_labels={"L": "Low", "M": "Medium", "H": "High"},
    ),
    Field(
        "air_temp_k",
        "Air temperature",
        "number",
        "conditions",
        "Ambient air temperature.",
        "Air temperature [K]",
        minimum=294,
        maximum=306,
        step=0.1,
        unit="K",
    ),
    Field(
        "process_temp_k",
        "Process temperature",
        "number",
        "conditions",
        "Temperature of the machining process.",
        "Process temperature [K]",
        minimum=304,
        maximum=316,
        step=0.1,
        unit="K",
    ),
    Field(
        "rotational_speed_rpm",
        "Rotational speed",
        "number",
        "operation",
        "Spindle speed.",
        "Rotational speed [rpm]",
        minimum=1100,
        maximum=3000,
        step=1,
        unit="rpm",
    ),
    Field(
        "torque_nm",
        "Torque",
        "number",
        "operation",
        "Torque on the spindle.",
        "Torque [Nm]",
        minimum=0,
        maximum=80,
        step=0.1,
        unit="Nm",
    ),
    Field(
        "tool_wear_min",
        "Tool wear",
        "number",
        "operation",
        "Minutes the current tool has been in use.",
        "Tool wear [min]",
        minimum=0,
        maximum=260,
        step=1,
        unit="min",
    ),
)

FIELDS_BY_NAME = {f.name: f for f in FIELDS}
NUMERIC_FEATURES = [f.name for f in FIELDS if f.kind == "number"]
CATEGORICAL_FEATURES = [f.name for f in FIELDS if f.kind == "category"]
FEATURE_ORDER = [f.name for f in FIELDS]

# Derived from the inputs with basic physics; computed identically for training and serving.
DERIVED_FEATURES = ["power_w", "temp_diff_k", "strain_min_nm"]
MODEL_FEATURES = [*FEATURE_ORDER, *DERIVED_FEATURES]

# Excluded on purpose: these flag *which kind* of failure happened, so they are only known after
# the failure. Using them would leak the answer into the model.
LEAKY_COLUMNS = ("TWF", "HDF", "PWF", "OSF", "RNF")
# Row id and serial number: identifiers, not machine properties.
ID_COLUMNS = ("UDI", "Product ID")


def add_derived(frame: pd.DataFrame) -> pd.DataFrame:
    out = frame.copy()
    out["power_w"] = out["torque_nm"] * out["rotational_speed_rpm"] * 2 * math.pi / 60
    out["temp_diff_k"] = out["process_temp_k"] - out["air_temp_k"]
    out["strain_min_nm"] = out["tool_wear_min"] * out["torque_nm"]
    return out


def clean_raw(raw: pd.DataFrame) -> pd.DataFrame:
    """Raw AI4I CSV → model-ready frame: renamed, leaks and ids removed, physics features added."""
    df = raw.drop(columns=[*LEAKY_COLUMNS, *ID_COLUMNS], errors="ignore")
    df = df.rename(columns={f.source_column: f.name for f in FIELDS})
    df[TARGET] = df.pop("Machine failure").astype(int)
    df[NUMERIC_FEATURES] = df[NUMERIC_FEATURES].astype(float)
    return add_derived(df[[*FEATURE_ORDER, TARGET]])[[*MODEL_FEATURES, TARGET]]


def records_to_frame(records: list[dict[str, Any]]) -> pd.DataFrame:
    """API inputs → the same columns `clean_raw` produces (minus the target)."""
    frame = pd.DataFrame(
        [{name: record.get(name) for name in FEATURE_ORDER} for record in records],
        columns=pd.Index(FEATURE_ORDER),
    )
    frame[NUMERIC_FEATURES] = frame[NUMERIC_FEATURES].astype(float)
    return add_derived(frame)[MODEL_FEATURES]
